package main

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

func main() {
	repo := "."
	entities := []string{
		"User", "Memo", "Attachment", "IdentityProvider", "Inbox",
		"InstanceSetting", "MemoRelation", "MemoShare", "Reaction",
		"UserIdentity", "UserSetting", "AuthenticationConfigState",
	}

	type result struct {
		entity string
		pkgs   []string
	}
	var results []result

	for _, entity := range entities {
		pat := regexp.MustCompile(`\bstore\.` + regexp.QuoteMeta(entity) + `\b`)
		pkgSet := map[string]bool{}
		filepath.Walk(".", func(path string, info os.FileInfo, err error) error {
			if err != nil || info.IsDir() {
				if info != nil && info.IsDir() {
					base := filepath.Base(path)
					if base == "store" || base == ".git" || strings.Contains(path, string(os.PathSeparator)+".git"+string(os.PathSeparator)) {
						return filepath.SkipDir
					}
					if strings.HasPrefix(path, "./store") || strings.HasPrefix(path, "store") {
						return filepath.SkipDir
					}
				}
				return nil
			}
			if !strings.HasSuffix(path, ".go") {
				return nil
			}
			if strings.Contains(path, "/store/") || strings.HasPrefix(path, "store/") {
				return nil
			}
			b, err := os.ReadFile(path)
			if err != nil {
				return nil
			}
			if pat.Match(b) {
				pkg := filepath.Dir(path)
				pkgSet[pkg] = true
			}
			return nil
		})
		pkgs := make([]string, 0, len(pkgSet))
		for p := range pkgSet {
			pkgs = append(pkgs, p)
		}
		sort.Strings(pkgs)
		results = append(results, result{entity, pkgs})
	}

	sort.Slice(results, func(i, j int) bool {
		if len(results[i].pkgs) != len(results[j].pkgs) {
			return len(results[i].pkgs) > len(results[j].pkgs)
		}
		return results[i].entity < results[j].entity
	})

	for _, r := range results {
		fmt.Printf("%s: %d\n", r.entity, len(r.pkgs))
		for _, p := range r.pkgs {
			fmt.Printf("  %s\n", p)
		}
		fmt.Println()
	}
}
